// Normalize the two configurable targets (authorized targets only).
const cfg = $input.first().json;
const out = [];
for (const key of ['target_1', 'target_2']) {
  let raw = String(cfg[key] || '').trim();
  if (!raw) continue;
  if (!/^https?:\/\//i.test(raw)) raw = 'http://' + raw;
  raw = raw.replace(/\/+$/, '');
  out.push({ json: { slot: key, target: raw } });
}
return out;

// Parse robots.txt Disallow entries and classify security.txt. No discovered path is ever requested.
const targets = $('Build Targets').all();
const robotsItems = $('Fetch robots.txt').all();
const secItems = $('Fetch security.txt').all();
const KEYWORDS = ['admin', 'backup', 'config', '.git', 'test'];

function errText(j) {
  if (!j || !j.error) return null;
  const e = j.error;
  const t = typeof e === 'string' ? e : (e.message || e.description || JSON.stringify(e));
  return String(t).slice(0, 300);
}
function bodyOf(j) {
  if (!j) return '';
  const b = j.data !== undefined ? j.data : j.body;
  if (b === undefined || b === null) return '';
  return typeof b === 'string' ? b : JSON.stringify(b);
}
function statusOf(j) {
  if (!j) return null;
  const s = j.statusCode !== undefined ? j.statusCode : j.status;
  return typeof s === 'number' ? s : (s ? Number(s) : null);
}
const looksHtml = (s) => /^\s*<(!doctype|html)/i.test(s);

const out = [];
for (let i = 0; i < targets.length; i++) {
  const target = targets[i].json.target;
  const rj = (robotsItems[i] || {}).json || {};
  const sj = (secItems[i] || {}).json || {};
  const fetchedAt = new Date().toISOString();

  // robots.txt
  const rErr = errText(rj);
  const rStatus = statusOf(rj);
  const rBody = bodyOf(rj);
  let robotsState = 'unknown';
  if (rErr) robotsState = 'inaccessible';
  else if (rStatus === 200 && !looksHtml(rBody)) robotsState = 'ok';
  else if (rStatus === 200) robotsState = 'unknown';
  else if (rStatus === 404 || rStatus === 410) robotsState = 'missing';
  else if (rStatus) robotsState = 'inaccessible';

  const candidates = [];
  let disallowCount = 0;
  if (robotsState === 'ok') {
    const seen = {};
    for (const line of rBody.split(/\r?\n/)) {
      const clean = line.split('#')[0].trim();
      const m = clean.match(/^disallow\s*:\s*(.*)$/i);
      if (!m) continue;
      const path = m[1].trim();
      if (!path) continue;
      disallowCount++;
      const low = path.toLowerCase();
      const hits = KEYWORDS.filter((k) => low.includes(k));
      if (hits.length && !seen[path] && candidates.length < 40) {
        seen[path] = true;
        candidates.push({ path: path, keywords: hits });
      }
    }
  }

  // security.txt
  const sErr = errText(sj);
  const sStatus = statusOf(sj);
  const sBody = bodyOf(sj);
  let secStatus = 'unknown';
  let warning = '';
  if (sErr) {
    secStatus = 'inaccessible';
    warning = 'WARNING: security.txt could not be retrieved (' + sErr + '). Not proof of a vulnerability.';
  } else if (sStatus === 200) {
    if (/^\s*contact\s*:/im.test(sBody) && !looksHtml(sBody)) {
      secStatus = 'present';
    } else {
      secStatus = 'unknown';
      warning = 'WARNING: HTTP 200 but content has no Contact field (possible soft-404/HTML page). Status unclear.';
    }
  } else if (sStatus === 404 || sStatus === 410) {
    secStatus = 'missing';
    warning = 'WARNING: security.txt is missing (HTTP ' + sStatus + '). No published disclosure contact; a hygiene gap, not proof of a vulnerability.';
  } else if (sStatus) {
    secStatus = 'inaccessible';
    warning = 'WARNING: security.txt returned HTTP ' + sStatus + ' (access error). Not proof of a vulnerability.';
  } else {
    warning = 'WARNING: security.txt status could not be determined.';
  }

  const robots = {
    httpStatus: rStatus,
    state: robotsState,
    error: rErr,
    disallowCount: disallowCount,
    excerpt: rBody.slice(0, 3000),
  };
  const securityTxt = { status: secStatus, httpStatus: sStatus, warning: warning };
  const agentInput = JSON.stringify({
    task: 'NGP-014',
    target: target,
    fetchedAt: fetchedAt,
    robotsTxt: robots,
    securityTxt: securityTxt,
    candidatePaths: candidates,
  });
  out.push({ json: { target: target, robots: robots, securityTxt: securityTxt, candidates: candidates, agentInput: agentInput } });
}
return out;

