const text = String(query || '');
const KEYWORDS = ['admin', 'backup', 'config', '.git', 'test'];
const found = [];
const seen = {};
for (const line of text.split(/\r?\n/)) {
  const clean = line.split('#')[0].trim();
  const m = clean.match(/^disallow\s*:\s*(.*)$/i);
  if (!m) continue;
  const path = m[1].trim();
  if (!path || seen[path]) continue;
  const low = path.toLowerCase();
  const hits = KEYWORDS.filter((k) => low.includes(k));
  if (hits.length) { seen[path] = true; found.push({ path: path, keywords: hits }); }
}
return JSON.stringify({ matches: found, count: found.length });

// SHA-256 of the exact AI input + hash-chained audit record (each row embeds the previous row hash).
const crypto = require('crypto');
const sha = (s) => crypto.createHash('sha256').update(String(s), 'utf8').digest('hex');
const agentItems = $('Recon Ranking Agent').all();
const normItems = $('Normalize & Analyze').all();
const last = $input.first().json || {};
let prev = last.record_sha256 ? String(last.record_sha256) : 'GENESIS';
const execId = String($execution.id);
const MODEL = 'gpt-5.4-mini';
const SEV = ['Info', 'Low', 'Medium'];
const V = ['INFO', 'LOW', 'MEDIUM'];
const rows = [];

for (let i = 0; i < normItems.length; i++) {
  const n = normItems[i].json;
  const a = (agentItems[i] || {}).json || {};
  const now = $now;
  const tsUtc = now.toUTC().toISO();
  const tsIst = now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd HH:mm:ss') + ' IST';

  let raw = a.output;
  const failed = !!a.error || raw === undefined || raw === null;
  if (typeof raw === 'string') { try { raw = JSON.parse(raw); } catch (e) { /* keep string */ } }
  const modelOutput = failed ? JSON.stringify({ error: a.error || 'no output' }) : (typeof raw === 'string' ? raw : JSON.stringify(raw));

  const steps = Array.isArray(a.intermediateSteps) ? a.intermediateSteps : [];
  const toolNames = steps.map((s) => (s.action && s.action.tool) || 'unknown');
  const toolArgs = JSON.stringify(steps.map((s) => (s.action && s.action.toolInput) || {})).slice(0, 2000);
  const toolSummary = steps.map((s) => String(typeof s.observation === 'string' ? s.observation : JSON.stringify(s.observation)).slice(0, 300)).join(' || ').slice(0, 1500);
  const toolUsed = steps.length > 0;

  // Sanitize: keep only paths really present in the fetched robots.txt candidate list.
  const allowed = {};
  for (const c of n.candidates) allowed[c.path] = true;
  let ranked = [];
  let dropped = 0;
  const parsed = (!failed && raw && typeof raw === 'object') ? raw : null;
  const entry = parsed && Array.isArray(parsed.targets) ? (parsed.targets[0] || {}) : {};
  const aiRanked = Array.isArray(entry.rankedTop6) ? entry.rankedTop6 : [];
  for (const r of aiRanked) {
    if (!r || !allowed[r.path]) { dropped++; continue; }
    if (ranked.find((x) => x.path === r.path)) continue;
    ranked.push({ path: r.path, reason: String(r.reason || '').slice(0, 300), severity: SEV.includes(r.severity) ? r.severity : 'Info' });
  }
  ranked = ranked.slice(0, 6).map((r, idx) => ({ rank: idx + 1, path: r.path, reason: r.reason, severity: r.severity }));

  let maxSev = 0;
  for (const r of ranked) maxSev = Math.max(maxSev, SEV.indexOf(r.severity));
  const aiVerdict = parsed && V.includes(String(parsed.verdict).toUpperCase()) ? String(parsed.verdict).toUpperCase() : null;
  const verdict = aiVerdict || V[maxSev];
  const summary = parsed && parsed.summary ? String(parsed.summary).slice(0, 300) : (failed ? 'AI analysis failed' : 'No summary');
  const status = failed ? 'AGENT_ERROR' : (toolUsed ? 'OK' : 'TOOL_NOT_CALLED');

  const inputHash = sha(n.agentInput);
  const fields = [prev, 'NGP-014', execId, n.target, inputHash, tsUtc, tsIst, modelOutput, verdict, verdict, toolNames.join(','), toolArgs, toolSummary, status];
  const recordHash = sha(fields.join('|'));

  rows.push({ json: {
    seq_key: execId + '-' + (i + 1),
    task_tag: 'NGP-014',
    execution_id: execId,
    target_url: n.target,
    canonical_input: n.agentInput,
    input_sha256: inputHash,
    timestamp_utc: tsUtc,
    timestamp_ist: tsIst,
    model_name: MODEL,
    model_output: modelOutput,
    verdict: verdict,
    severity: verdict,
    tool_name: toolNames.join(','),
    tool_arguments: toolArgs,
    tool_result_summary: toolSummary,
    workflow_status: status,
    prev_record_sha256: prev,
    record_sha256: recordHash,
    view: { target: n.target, securityTxt: n.securityTxt, ranked: ranked, dropped: dropped, summary: summary, verdict: verdict, status: status },
  } });
  prev = recordHash;
}
return rows;

const rows = $('Build Audit Records').all().map((i) => i.json);
const esc = (s) => String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const V = ['INFO', 'LOW', 'MEDIUM'];
let maxV = 0;
let leads = 0;
let notPresent = 0;
for (const r of rows) {
  maxV = Math.max(maxV, V.indexOf(r.view.verdict));
  leads += r.view.ranked.length;
  if (r.view.securityTxt.status !== 'present') notPresent++;
}
const verdict = V[Math.max(maxV, 0)];
const first = rows[0] || { execution_id: String($execution.id), timestamp_ist: '' };
const oneLine = rows.length + ' targets, ' + leads + ' ranked leads, security.txt not present on ' + notPresent;
const lines = [];
lines.push('\uD83D\uDD34 NGP-014 | exec #' + first.execution_id + ' | ' + first.timestamp_ist + ' | ' + verdict + ' | ' + oneLine);
for (const r of rows) {
  const v = r.view;
  lines.push('');
  lines.push('<b>Target:</b> ' + esc(v.target));
  const st = v.securityTxt;
  lines.push('security.txt: <b>' + esc(String(st.status).toUpperCase()) + '</b>' + (st.httpStatus ? ' (HTTP ' + st.httpStatus + ')' : ''));
  if (st.status !== 'present' && st.warning) lines.push(esc(st.warning));
  lines.push('Verdict: ' + esc(v.verdict) + (v.status !== 'OK' ? ' [' + esc(v.status) + ']' : ''));
  if (v.ranked.length) {
    lines.push('Top leads (recon only):');
    for (const x of v.ranked) lines.push(x.rank + '. ' + esc(x.path) + ' [' + esc(x.severity) + '] ' + esc(x.reason));
  } else {
    lines.push('Top leads: none matched admin/backup/config/.git/test');
  }
  lines.push('Input SHA-256: <code>' + esc(r.input_sha256) + '</code>');
  lines.push('Record SHA-256: <code>' + esc(r.record_sha256) + '</code>');
}
lines.push('');
lines.push('Leads are reconnaissance hints only; no discovered path was visited.');
return [{ json: { message: lines.join(String.fromCharCode(10)) } }];
